"""Provide the owned CODE-EVAL-005 mask_reference fixture."""

import logging

logger = logging.getLogger(__name__)


def mask_reference(token, keep):
    """Retain a suffix only when its length is positive and smaller than the reference; replace every preceding character with period. Otherwise replace the entire reference with periods."""
    logger.info("ce005_fixture_called function=mask_reference")
    if keep <= 0 or keep >= len(token):
        return "." * len(token)
    return "." * (len(token)-keep) + token[-keep:]

"""Provide the owned CODE-EVAL-005 clamped_slot fixture."""

import logging

logger = logging.getLogger(__name__)


def clamped_slot(position, length):
    """Return a valid zero-based slot by clamping the proposed position; a nonpositive slot count is invalid and raises ValueError."""
    logger.info("ce005_fixture_called function=clamped_slot")
    if length <= 0:
        raise ValueError("empty length")
    return max(0,min(position,length-1))
